script:
(function () {
	function cleanFmt(val) {
		if (val === null || val === undefined) return "0.00 د.ل";
		var num = parseFloat(val) || 0;
		return num.toLocaleString('ar-LY', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " د.ل";
	}

	var root = (typeof root_element !== "undefined" && root_element) ? root_element : document;

	frappe.call({
		method: "hajj_umrah_manager.api.get_dashboard_stats",
		callback: function (r) {
			if (!r.message) return;
			var d = r.message;
			var el1 = root.querySelector("#hu-total-pilgrims");
			if (el1) el1.innerText = (d.total_pilgrims || 0).toLocaleString('ar-LY');
			var el2 = root.querySelector("#hu-total-trips");
			if (el2) el2.innerText = (d.total_trips || 0).toLocaleString('ar-LY');
			var el3 = root.querySelector("#hu-treasury-balance");
			if (el3) el3.innerText = cleanFmt(d.current_treasury_balance);
			var el4 = root.querySelector("#hu-total-profit");
			if (el4) el4.innerText = cleanFmt(d.total_profit);
			var el5 = root.querySelector("#hu-total-collected");
			if (el5) el5.innerText = cleanFmt(d.total_collected);
		},
	});

	var popCards = root.querySelectorAll(".hu-pop-card");
	popCards.forEach(function (card) {
		card.onmouseenter = function () {
			card.style.transform = "translateY(-6px) scale(1.02)";
			card.style.boxShadow = "0 12px 24px -4px rgba(4, 120, 87, 0.15), 0 4px 10px -2px rgba(16, 24, 40, 0.06)";
			card.style.borderColor = "#047857";
		};
		card.onmouseleave = function () {
			card.style.transform = "translateY(0) scale(1)";
			card.style.boxShadow = "0 2px 4px rgba(16, 24, 40, 0.03)";
			card.style.borderColor = "#eaecf0";
		};
	});

	var popBtns = root.querySelectorAll(".hu-pop-btn");
	popBtns.forEach(function (btn) {
		btn.onmouseenter = function () {
			btn.style.transform = "translateX(-5px)";
			btn.style.backgroundColor = "#f1f5f9";
			btn.style.borderColor = "#cbd5e1";
			var arrow = btn.querySelector("span:last-child");
			if (arrow) arrow.style.color = "#047857";
		};
		btn.onmouseleave = function () {
			btn.style.transform = "translateX(0)";
			btn.style.backgroundColor = "#f8fafc";
			btn.style.borderColor = "#e2e8f0";
			var arrow = btn.querySelector("span:last-child");
			if (arrow) arrow.style.color = "#94a3b8";
		};
	});

	var primaryBtns = root.querySelectorAll(".hu-pop-btn-primary");
	primaryBtns.forEach(function (btn) {
		btn.onmouseenter = function () {
			btn.style.transform = "translateX(-5px) translateY(-2px)";
			btn.style.backgroundColor = "#065f46";
			btn.style.boxShadow = "0 6px 16px rgba(4, 120, 87, 0.3)";
		};
		btn.onmouseleave = function () {
			btn.style.transform = "translateX(0) translateY(0)";
			btn.style.backgroundColor = "#047857";
			btn.style.boxShadow = "none";
		};
	});

	var navCards = root.querySelectorAll("[data-route]");
	navCards.forEach(function (card) {
		card.onclick = function () {
			var dt = card.getAttribute("data-route");
			if (!dt) return;
			if (dt === "Company Treasury") {
				frappe.set_route("Form", "Company Treasury", "Company Treasury");
			} else if (dt === "Role Permission Manager") {
				frappe.set_route("page", "permission-manager");
			} else {
				frappe.set_route("List", dt);
			}
		};
	});

	var filterCards = root.querySelectorAll("[data-route-filter]");
	filterCards.forEach(function (card) {
		card.onclick = function () {
			var mode = card.getAttribute("data-route-filter");
			if (mode) {
				frappe.route_options = { "payment_type": mode };
				frappe.set_route("List", "Umrah Booking");
			}
		};
	});

	var newCards = root.querySelectorAll("[data-route-new]");
	newCards.forEach(function (card) {
		card.onclick = function () {
			var dt = card.getAttribute("data-route-new");
			if (dt) frappe.new_doc(dt);
		};
	});

})();

// إنشاء ستايل جديد وحقنه في النظام لضمان تخطي قيود العزل
