(function() {
    const container = root_element.querySelector('.cards-grid');

    const mainCards = [
        {
            title: 'نظام المبيعـــــات',
            items: [
                {label:'حسابات البيع', type:'doctype', target:'POS Profile', icon:'🏢'},
