                {label:'حجز مسبق', type:'doctype', target:'Sales Order', icon:'📅'},
                {label:'قائمة الأصناف', type:'doctype', target:'Item', icon:'📦'}
            ]
        },
        {
            title: 'التقارير والإحصائيات',
            items: [
                {label:'ملخص مبيعات الفواتير', type:'report', target:'Sales Invoice Trends', icon:'📊'},
                {label:'تحليل الطلبات المسبقة', type:'report', target:'Sales Order Analysis', icon:'📈'},
                {label:'تحليل فرص المبيعات المستقبلية', type:'report', target:'Sales Pipeline Analytics', icon:'📉'},
                {label:'تقارير الارباح والمنتجات', type:'report', target:'Sales Analytics', icon:'💰'}
            ]
        }
    ];

    mainCards.forEach(cardData => {
        const mainCard = document.createElement('div');
        mainCard.className = 'main-card';
        mainCard.innerHTML = `<h2>${cardData.title}</h2>`;

        const subGrid = document.createElement('div');
        subGrid.className = 'sub-cards';

        cardData.items.forEach(item => {
            const subCard = document.createElement('div');
            subCard.className = 'sub-card';
            subCard.innerHTML = `<div class="icon-wrap">${item.icon}</div><span>${item.label}</span>`;

            // === الربط المحفوظ ===
            subCard.addEventListener('click', () => {
                if(item.type === 'doctype') frappe.set_route('List', item.target);
                else if(item.type === 'report') frappe.set_route('query-report', item.target);
                else if(item.type === 'page') frappe.set_route('page', item.target);
                else if(item.type === 'url') window.open(item.target, '_blank');
            });

            // Ripple Effect
            subCard.addEventListener('click', (e) => {
                const rect = subCard.getBoundingClientRect();
                const ripple = document.createElement('span');
                const size = Math.max(rect.width, rect.height);
                const x = e.clientX - rect.left - size/2;
                const y = e.clientY - rect.top - size/2;

                ripple.style.position = 'absolute';
                ripple.style.left = x + 'px';
                ripple.style.top = y + 'px';
                ripple.style.width = ripple.style.height = size + 'px';
                ripple.style.borderRadius = '50%';
                ripple.style.background = 'rgba(11,81,100,0.2)';
                ripple.style.transform = 'scale(0)';
                ripple.style.pointerEvents = 'none';
                ripple.style.transition = 'transform .6s ease, opacity .8s ease';
                subCard.appendChild(ripple);

                requestAnimationFrame(() => { ripple.style.transform = 'scale(1.8)'; ripple.style.opacity='0'; });
                setTimeout(()=> ripple.remove(), 800);
            });

            subGrid.appendChild(subCard);
        });

        mainCard.appendChild(subGrid);
        container.appendChild(mainCard);
    });
})();

