script:
(() => {
  const el = typeof root_element !== "undefined" ? root_element : document;
  const nameEl = el.querySelector("#full_name");
  const clockEl = el.querySelector("#clock");
  const dateEl = el.querySelector("#date");

  // جلب اسم المستخدم من النظام
  frappe.call({
    method: "frappe.client.get",
    args: { doctype: "User", name: frappe.session.user },
    callback(r) {
      if (!nameEl) return;
      const fullName =
        (r.message && (r.message.full_name || r.message.username)) ||
        frappe.session.user;
      nameEl.textContent = fullName;
    },
  });

  function updateClock() {
    const now = new Date();

    // الوقت
    if (clockEl) {
      clockEl.textContent = now.toLocaleTimeString("ar-LY", {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      });
    }

    // الميلادي
    const gregDate = now.toLocaleDateString("ar-LY", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });

    // الهجري (أم القرى)
    const hijriDate = new Intl.DateTimeFormat("ar-SA", {
      calendar: "islamic-umalqura",
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(now);

    if (dateEl) {
      dateEl.innerHTML = `
        <div class="greg-line">${gregDate} م</div>
        <div class="hijri-line">${hijriDate} هـ</div>
      `;
    }
  }

  if (el.__clockTimer) clearInterval(el.__clockTimer);
  updateClock();
  el.__clockTimer = setInterval(updateClock, 1000);
})();

